export function applyMaterialSelectionReview(){
 const missing=Object.keys(materialSelectionCopy).filter(id=>!review[materialSelectionCopy[id]]);if(missing.length)throw Error('Missing material translations: '+missing.join(', '));
 fs.writeFileSync('translations/material-selection-review.json',JSON.stringify(review,null,2)+'\n');
 for(const locale of ['de','es','it','fr','zh']){const file='translations/'+locale+'.json',d=JSON.parse(fs.readFileSync(file,'utf8'));for(const [source,values]of Object.entries(review))d[source]=values[locale];for(const [id,source]of Object.entries(materialSelectionCopy))if(id.endsWith('Title')&&review[source])d[source+' | ZUFEK']=review[source][locale]+' | ZUFEK';for(const [id,source]of Object.entries(materialSelectionCopy))if(id.endsWith('Source')&&review[source])d[source+' ↗']=review[source][locale]+' ↗';fs.writeFileSync(file,JSON.stringify(d,null,2)+'\n');}
 return Object.keys(review).length;
}
if(process.argv[1]?.replaceAll('\\','/').endsWith('/material-selection-localization.mjs'))console.log('Applied material selection translations: '+applyMaterialSelectionReview());
